// CabinetOS Game events: each person's games go to their own Telegram chat.
// The bot's token from BotFather, then one line per person: the name exactly
// as the console shows it, then that person's chat number. Anyone not listed
// goes nowhere.
const TOKEN = "PASTE-THE-BOT-TOKEN";
const PEOPLE = {
  "First person": "PASTE-THEIR-CHAT-NUMBER",
  "Second person": "PASTE-THEIR-CHAT-NUMBER",
};
// The messages to send. Delete the ones you do not want: with only
// "game_started" left, only game starts are posted.
const SEND = ["game_started", "game_paused", "game_resumed", "game_ended", "achievement_unlocked", "set_completed"];
// Between these hours (the console's clock, 0 to 23) messages arrive without a
// sound. The same hour twice keeps every message sounding.
const QUIET_FROM = 22, QUIET_UNTIL = 7;

const bot = `https://api.telegram.org/bot${TOKEN}`;
// Whoever opens the bot and presses Start is sent their chat number with the
// console's test message (press Done on its address), to put next to their
// name above. A failure here never holds up a game's message.
if ($input.first().json.body?.event === 'test') {
  try {
    const updates = await this.helpers.httpRequest({ url: `${bot}/getUpdates`, json: true });
    let last = 0;
    for (const u of updates.result ?? []) {
      last = u.update_id;
      if (u.message?.text?.startsWith('/start')) {
        const chat = u.message.chat.id;
        await this.helpers.httpRequest({ method: 'POST', url: `${bot}/sendMessage`, json: true,
          body: { chat_id: chat, text: `Your chat number is ${chat}. In n8n, put it next to your name in Sort by person.` } });
      }
    }
    if (last) await this.helpers.httpRequest({ url: `${bot}/getUpdates?offset=${last + 1}`, json: true });
  } catch (error) {
    // The next test message tries again.
  }
}

const COVER = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function minutes(n) {
  if (!n) return 'less than a minute';
  return n === 1 ? '1 minute' : `${n} minutes`;
}
function quietHour(time) {
  const hour = Number(String(time).slice(11, 13));
  return QUIET_FROM > QUIET_UNTIL ? hour >= QUIET_FROM || hour < QUIET_UNTIL : hour >= QUIET_FROM && hour < QUIET_UNTIL;
}

const out = [];
for (const item of $input.all()) {
  const m = item.json.body ?? {};
  const chat = PEOPLE[m.person];
  if (!chat || !SEND.includes(m.event)) continue;
  const linkup = m.linkup_game === 'hosting' || m.linkup_game === 'joined';
  const over = linkup ? ' over LinkUp' : '';
  const who = `<b>${esc(m.person)}</b>`, game = `<b>${esc(m.game)}</b>`;
  const points = m.points === 1 ? '1 point' : `${m.points} points`;

  // Started and every achievement: the cover, with the game and system under it.
  let card = null;
  if (m.event === 'game_started') {
    card = m.linkup_game === 'joined' ? `🤝 ${who} joined a LinkUp game`
         : linkup ? `🤝 ${who} started playing over LinkUp`
         : `🎮 ${who} started playing`;
  } else if (m.event === 'set_completed') {
    card = `🌟 ${who} unlocked every achievement${over}`;
  }
  // The rest: one line each.
  const line = {
    game_paused: `⏸️ ${who} paused ${game}${over}`,
    game_resumed: `▶️ ${who} is back in ${game}${over}`,
    game_ended: `🛑 ${who} stopped playing ${game}${over} after ${minutes(m.minutes_played)}`,
    achievement_unlocked: `🏆 ${who} unlocked <b>${esc(m.achievement)}</b> (${points}) in ${game}${over}`,
  }[m.event];
  if (!card && !line) continue;

  const text = card ? [card, game, esc(m.system)].filter(Boolean).join('\n') : line;
  // Pause and resume, and anything in the quiet hours, arrive without a sound.
  const quiet = m.event === 'game_paused' || m.event === 'game_resumed' || quietHour(m.time);
  const post = { json: { cover: false, url: `${bot}/sendMessage`,
                         payload: { chat_id: chat, text, parse_mode: 'HTML', disable_notification: quiet } } };
  const type = COVER[m.cover_type];
  if (card && m.cover && type) {
    post.json.cover = true;
    post.json.url = `${bot}/sendPhoto`;
    post.json.payload = { chat_id: String(chat), caption: text, disable_notification: String(quiet) };
    post.binary = { cover: { data: m.cover, mimeType: m.cover_type, fileName: `cover.${type}` } };
  }
  out.push(post);
}
return out;
